print(enc)
print(caesar(enc, -3) == 'Attack at Dawn!', caesar(enc, 23))

def counts(s):
    v = 'aeiou'
    vc = 0
    cc = 0
    for ch in s.lower():
        if 'a' <= ch <= 'z':
            if ch in v:
                vc += 1
            else:
                cc += 1
    return [vc, cc]
