def compress(s):
    if s == '':
        return ''
    out = ''
    cur = s[0]
    n = 1
    for ch in s[1:]:
        if ch == cur:
            n += 1
        else:
            out += cur + str(n)
            cur = ch
            n = 1
    return out + cur + str(n)
print(compress('aaabbbcccd'), compress('abc'), compress(''))
def expand(s):
    out = ''
    i = 0
    while i < len(s):
        ch = s[i]
        i += 1
        num = ''
        while i < len(s) and '0' <= s[i] <= '9':
            num += s[i]
            i += 1
        out += ch * int(num)
    return out
